/* Manoir Pokémon : statue Rhinocorne, tapis et table, trou dans le plancher et murs à pilastres découpés dans des captures de Pokémon Let's Go envoyées par Raphaël (voir CREDITS.md) */
const MN = { img:null, R:{"statue":[0,0,72,124],"carpet":[74,0,380,260],"hole":[456,0,205,282],"wtop":[663,0,20,75],"wface":[685,0,241,94],"wpil":[928,0,89,100]}, K:.48, pat:null, page:null };
(() => { const im = new Image(); im.onload = () => { MN.img = im; MN.pat = null; for (const c of chunkData.values()) c.canvas = null; }; im.src = "data:image/png;base64,";
  const pg = new Image(); pg.src = "data:image/jpeg;base64,"; MN.page = pg; })();
// flamme « Erupting Flame » de HarmoKnight (modèle 3D rendu en 6 images de 40x81, texture qui défile)
(() => { const im = new Image(); im.onload = () => { MN.flame = im; }; im.src = "data:image/png;base64,"; })();
const manorOn = () => LEVEL.manor && MN.img;
function mnSpr(g, n, x, y, w, h) { const r = MN.R[n]; g.drawImage(MN.img, r[0], r[1], r[2], r[3], x, y, w ?? r[2] * MN.K, h ?? r[3] * MN.K); }
function mnFloorPattern(g) { // dalles beiges posées en losange, joints sombres, grain léger (couleurs de la capture)
  const P = 44, c = document.createElement("canvas"); c.width = c.height = P * 2; const x = c.getContext("2d");
  x.fillStyle = "rgb(140,128,101)"; x.fillRect(0, 0, P * 2, P * 2);
  const R = rng(77); for (let i = 0; i < 900; i++) { x.fillStyle = R() < .5 ? "rgba(255,245,215,.08)" : "rgba(60,50,30,.07)"; x.fillRect(R() * P * 2, R() * P * 2, 1 + R() * 2, 1 + R() * 2); }
  for (const [cx0, cy0, v] of [[P, 0, 6], [0, P, -4], [P * 2, P, -4], [P, P * 2, 6], [0, -P, 0]]) { // un ton par losange
    x.fillStyle = v > 0 ? `rgba(255,240,205,${v / 100})` : `rgba(50,40,20,${-v / 100})`; x.beginPath(); x.moveTo(cx0, cy0 - P); x.lineTo(cx0 + P, cy0); x.lineTo(cx0, cy0 + P); x.lineTo(cx0 - P, cy0); x.closePath(); x.fill(); }
  x.strokeStyle = "rgba(78,66,46,.75)"; x.lineWidth = 2.2;
  for (const o of [-P * 2, 0, P * 2]) { x.beginPath(); x.moveTo(o, 0); x.lineTo(o + P * 2, P * 2); x.moveTo(o + P * 2, 0); x.lineTo(o, P * 2); x.stroke(); }
  x.strokeStyle = "rgba(235,222,190,.35)"; x.lineWidth = 1;
  for (const o of [-P * 2, 0, P * 2]) { x.beginPath(); x.moveTo(o, 2); x.lineTo(o + P * 2, P * 2 + 2); x.moveTo(o + P * 2, 2); x.lineTo(o, P * 2 + 2); x.stroke(); }
  return g.createPattern(c, "repeat");
}
function mnWallH(g, xa, xb, yb) { // pan de mur horizontal : dessus brun, façade à panneaux entre deux pilastres, bas posé en yb
  const K = MN.K, pw = MN.R.wpil[2] * K, ph = MN.R.wpil[3] * K, fh = MN.R.wface[3] * K, th = MN.R.wtop[3] * K, L = xb - xa;
  ell(g, (xa + xb) / 2, yb + 4, L / 2 + 10, 9, "rgba(20,10,4,.35)");
  mnSpr(g, "wtop", xa, yb - fh - th + 2, L, th);
  const p0 = L >= 150, p1 = L >= 70, m = L - pw * (p0 + p1), n = Math.max(1, Math.round(m / (MN.R.wface[2] * K))), xs = xa + (p0 ? pw : 0); // pilastres seulement si la place le permet
  if (m > 4) for (let k = 0; k < n; k++) mnSpr(g, "wface", xs + k * m / n, yb - fh, m / n + .5, fh);
  if (p0) mnSpr(g, "wpil", xa, yb - ph, pw, ph); if (p1) mnSpr(g, "wpil", xb - pw, yb - ph, pw, ph);
}
function mnWallV(g, x, ya, yb) { // pan de mur vertical : on voit le dessus brun, et la façade au bout
  const K = MN.K, pw = MN.R.wpil[2] * K, ph = MN.R.wpil[3] * K, W = 30;
  g.fillStyle = "rgba(20,10,4,.3)"; g.fillRect(x - W / 2 + 6, ya, W, yb - ya);
  g.fillStyle = "#3e2a20"; g.fillRect(x - W / 2, ya - ph + 4, W, yb - ya);
  g.fillStyle = "#5a3a2a"; g.fillRect(x - W / 2 + 3, ya - ph + 7, W - 6, yb - ya - 6);
  g.fillStyle = "rgba(255,220,180,.12)"; g.fillRect(x - W / 2 + 3, ya - ph + 7, 3, yb - ya - 6);
  mnSpr(g, "wpil", x - pw / 2, yb - ph, pw, ph);
}
function renderManorHG(ci, cj) {
  const c = getChunk(ci, cj), x0 = ci * CH, y0 = cj * CH, K = MN.K;
  const cv2 = document.createElement("canvas"); cv2.width = cv2.height = CH * CH_SCALE;
  const g = cv2.getContext("2d"); g.scale(CH_SCALE, CH_SCALE); g.translate(-x0, -y0); g.imageSmoothingEnabled = true;
  if (!MN.pat) MN.pat = mnFloorPattern(g);
  g.fillStyle = MN.pat; g.fillRect(x0, y0, CH, CH);
  const R = rng(Math.floor(hash(ci - 515, cj + 919) * 4294967295));
  for (let i = 0; i < 9; i++) { const x = x0 + R() * CH, y = y0 + R() * CH, n = fbm(x / 300, y / 300); // taches d'humidité et de poussière
    const gr = g.createRadialGradient(x, y, 0, x, y, 60 + R() * 60); gr.addColorStop(0, `rgba(70,58,36,${.08 + n * .1})`); gr.addColorStop(1, "rgba(70,58,36,0)"); g.fillStyle = gr; g.fillRect(x - 130, y - 130, 260, 260); }
  g.strokeStyle = "rgba(60,48,30,.7)"; g.lineWidth = 1.3; // fissures dans le carrelage
  for (let i = 0; i < 5; i++) { let x = x0 + R() * CH, y = y0 + R() * CH, a = R() * 6; g.beginPath(); g.moveTo(x, y); for (let k = 0; k < 5; k++) { a += (R() - .5) * 1.6; x += Math.cos(a) * 10; y += Math.sin(a) * 10; g.lineTo(x, y); } g.stroke(); }
  for (let i = 0; i < 14; i++) { const x = x0 + R() * CH, y = y0 + R() * CH, s = 2 + R() * 4; g.fillStyle = R() < .5 ? "#b8a888" : "#9a8a6a"; g.beginPath(); g.moveTo(x - s, y); g.lineTo(x, y - s * .7); g.lineTo(x + s * 1.2, y + s * .2); g.lineTo(x, y + s * .6); g.closePath(); g.fill(); } // éclats
  // tapis rouge le long du couloir principal (Rouge Feu / Vert Feuille)
  const band = (w, col) => { g.strokeStyle = col; g.lineWidth = w; g.lineCap = "butt"; g.beginPath(); for (let x = x0 - 40; x <= x0 + CH + 40; x += 16) x === x0 - 40 ? g.moveTo(x, pathY(x)) : g.lineTo(x, pathY(x)); g.stroke(); };
  band(96, "rgba(40,20,10,.3)"); band(90, "#c89a50"); band(84, "#9a3a34"); band(70, "#b04a40");
  const all = { mwalls:[], shelves:[], statues:[], fires:[] };
  for (let a = -1; a <= 1; a++) for (let b2 = -1; b2 <= 1; b2++) { const n = getChunk(ci + a, cj + b2); for (const k in all) all[k].push(...(n[k] || [])); }
  // trou dans le plancher (un morceau de carte sur deux)
  for (let a = -1; a <= 1; a++) for (let b2 = -1; b2 <= 1; b2++) { const h = mnHole(ci + a, cj + b2); if (!h) continue;
    const r = MN.R.hole, k = .5; mnSpr(g, "hole", h.x - r[2] * k / 2, h.y - r[3] * k / 2, r[2] * k, r[3] * k); }
  for (const q of all.shelves) { const r = MN.R.carpet, k = .5; mnSpr(g, "carpet", q.x - r[2] * k * .55, q.y - r[3] * k * .45, r[2] * k, r[3] * k); } // tapis bleu, table et papiers
  for (const f of all.fires) { g.save(); g.translate(f.x, f.y); g.rotate(f.a); // grilles des portes de feu (flammes animées dans drawCaveLight)
    g.fillStyle = "#2a2420"; g.fillRect(-f.len / 2, -9, f.len, 18); g.strokeStyle = "#6a6258"; g.lineWidth = 2; g.strokeRect(-f.len / 2, -9, f.len, 18);
    for (let k = -f.len / 2 + 8; k < f.len / 2; k += 10) { g.beginPath(); g.moveTo(k, -8); g.lineTo(k, 8); g.stroke(); }
    g.restore(); }
  const items = [];
  for (const w of all.mwalls) {
    const L = w.len / 2, gap = w.broken > .5 ? [L * .15, L * .45] : null, segs = gap ? [[-L, gap[0]], [gap[1], L]] : [[-L, L]];
    if (w.a === 0) for (const [a, b] of segs) items.push([w.y + 14, () => mnWallH(g, w.x + a, w.x + b, w.y + 14)]);
    else for (const [a, b] of segs) items.push([w.y + b, () => mnWallV(g, w.x, w.y + a, w.y + b)]);
    if (gap) for (let q = 0; q < 6; q++) { const m = (gap[0] + gap[1]) / 2, ox = w.a === 0 ? m : 0, oy = w.a === 0 ? 0 : m;
      items.push([w.y + oy, () => { const s = 4 + q % 3 * 2; g.fillStyle = q % 2 ? "#c8b48e" : "#a8946e"; g.beginPath(); const x = w.x + ox + (hash(q, w.y) - .5) * 34, y = w.y + oy + (hash(w.x, q) - .5) * 30; g.moveTo(x - s, y); g.lineTo(x, y - s); g.lineTo(x + s, y + s * .3); g.closePath(); g.fill(); }]); }
  }
  for (const q of all.statues) items.push([q.y + 12, () => { const r = MN.R.statue, k = .66; ell(g, q.x, q.y + 10, 22, 8, "rgba(20,10,4,.35)"); mnSpr(g, "statue", q.x - r[2] * k / 2, q.y + 16 - r[3] * k, r[2] * k, r[3] * k); }]);
  items.sort((a, b) => a[0] - b[0]); for (const it of items) it[1]();
  c.canvas = cv2; return cv2;
}
// page du journal ramassée : l'illustration telle quelle, avec sa traduction en français dessous
// trou dans le plancher : un morceau de carte sur deux, infranchissable (solides dans manorChunk)
function mnHole(i, j) {
  if (hash(i * 3.3 + 1, j * 1.7 - 2) > .5) return null;
  const x = i * CH + 90 + hash(i, j + 5) * (CH - 180), y = j * CH + 90 + hash(i + 7, j) * (CH - 180);
  return nearPath(x, y, 110) || Math.hypot(x, y - START_Y) < 300 ? null : { x, y };
}
function showJournalPage(n) {
  let el = document.getElementById("jPage");
  if (!el) { el = document.createElement("div"); el.id = "jPage";
    el.style.cssText = "position:fixed;right:max(16px,env(safe-area-inset-right,0px));top:50%;transform:translateY(-50%);z-index:40;pointer-events:none;width:min(300px,38vw);display:flex;flex-direction:column;gap:8px;transition:opacity .4s;filter:drop-shadow(0 8px 16px rgba(0,0,0,.6))";
    el.innerHTML = '<img alt="Page du journal" style="width:100%;border-radius:6px;display:block"><div style="background:rgba(30,20,12,.88);color:#f4e8cc;font:600 13px/1.45 Rubik,sans-serif;padding:10px 12px;border-radius:8px;border:2px solid #8a6a3a"></div>';
    document.body.appendChild(el); }
  el.querySelector("img").src = MN.page.src; el.querySelector("div").textContent = JOURNAL[n]; el.style.opacity = 1; el.hidden = false;
  clearTimeout(showJournalPage.t); showJournalPage.t = setTimeout(() => { el.style.opacity = 0; setTimeout(() => el.hidden = true, 450); }, 3500);
}
